<template>
  <section class="admin-page settings-page"><PageHeader title="系统设置" description="运行环境、联系支持、数据库状态与开发工具"><template #actions><t-button variant="outline" :loading="refreshing" @click="load(true)"><template #icon><i-refresh theme="outline" /></template>刷新</t-button></template></PageHeader><LoadingState v-if="loading"/><ErrorState v-else-if="loadError" :message="loadError" retryable @retry="load()"/><template v-else><section class="runtime-strip"><div><span>Node.js</span><strong>{{overview.runtime.nodeVersion}}</strong></div><div><span>平台</span><strong>{{overview.runtime.platform}}</strong></div><div><span>环境</span><strong>{{overview.runtime.environment}}</strong></div><div><span>数据表</span><strong>{{overview.database.tables.length}}</strong></div></section><section class="data-section"><div class="section-heading"><h2>联系支持</h2><span>Creator 公开信息</span></div><div class="support-form"><label><span>启用联系方式</span><t-switch data-testid="support-enabled" :value="supportForm.enabled" @change="supportForm.enabled=$event===true"/></label><label><span>标题</span><t-input v-model="supportForm.title"/></label><label><span>微信号</span><t-input data-testid="support-wechat-id" v-model="supportForm.wechatId"/></label><label><span>二维码资源 ID</span><t-input data-testid="support-qr-asset-id" v-model="supportForm.qrAssetId" placeholder="support/wechat.png"/></label><label><span>说明</span><t-input v-model="supportForm.description"/></label><t-button data-testid="save-support-contact" theme="primary" :loading="supportSaving" @click="saveSupport">保存联系方式</t-button></div></section><section class="data-section"><div class="section-heading"><h2>开发工具</h2></div><div class="setting-row"><div><strong>AI 调试工具</strong><small>运行时开关</small></div><t-switch :value="overview.development.aiDevToolsEnabled" :loading="saving" :disabled="!overview.capabilities.updateDevelopment" @change="changeDevelopment"/></div></section><p v-if="operationMessage" class="operation-message" :class="{error:operationFailed}" role="status">{{operationMessage}}</p><section class="data-section"><div class="section-heading"><h2>数据库表</h2><span>{{overview.database.tables.length}} 张</span></div><div class="table-scroll"><table><thead><tr><th>表名</th><th>记录数</th></tr></thead><tbody><tr v-for="table in overview.database.tables" :key="table.name"><td><code>{{table.name}}</code></td><td>{{table.rowCount}}</td></tr></tbody></table></div></section></template></section>
</template>
<script setup lang="ts">
import{onMounted,reactive,ref}from"vue";import PageHeader from"../components/PageHeader.vue";import LoadingState from"../components/LoadingState.vue";import ErrorState from"../components/ErrorState.vue";import{adminErrorText,getSupportContact,getSystemOverview,updateDevelopmentSettings,updateSupportContact,type SystemOverview}from"../api/adminApi";
const empty=():SystemOverview=>({database:{tables:[]},development:{aiDevToolsEnabled:false},runtime:{nodeVersion:"-",platform:"-",environment:"-"},capabilities:{updateDevelopment:false,clearDatabase:false,importDatabase:false,exportDatabase:false}});const overview=ref(empty());const supportForm=reactive({enabled:false,type:"wechat" as const,title:"联系支持",wechatId:"",qrAssetId:"",description:""});const loading=ref(true);const refreshing=ref(false);const loadError=ref("");const saving=ref(false);const supportSaving=ref(false);const operationMessage=ref("");const operationFailed=ref(false);async function load(silent=false){if(silent)refreshing.value=true;else loading.value=true;loadError.value="";try{const[system,support]=await Promise.all([getSystemOverview(),getSupportContact()]);overview.value=system;Object.assign(supportForm,{enabled:support.enabled,type:support.type,title:support.title,wechatId:support.wechatId,qrAssetId:support.qrCodeUrl?.replace(/^\/oss\//,"")||"",description:support.description})}catch(cause){loadError.value=adminErrorText(cause,"系统状态加载失败")}finally{loading.value=false;refreshing.value=false}}async function saveSupport(){supportSaving.value=true;try{await updateSupportContact({...supportForm,qrAssetId:supportForm.qrAssetId||null});operationFailed.value=false;operationMessage.value="联系支持配置已保存"}catch(cause){operationFailed.value=true;operationMessage.value=adminErrorText(cause,"联系支持配置保存失败")}finally{supportSaving.value=false}}async function changeDevelopment(value:unknown){const enabled=value===true;saving.value=true;try{await updateDevelopmentSettings(enabled);await load(true);operationFailed.value=false;operationMessage.value="开发工具设置已更新"}catch(cause){operationFailed.value=true;operationMessage.value=adminErrorText(cause,"开发工具设置更新失败")}finally{saving.value=false}}onMounted(()=>load());
</script>
